import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Monitor.
 *
 * @stability experimental
 */
export interface IMonitorRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Monitor resource.
     */
    readonly monitorRef: MonitorReference;
}
/**
 * A reference to a Monitor resource.
 *
 * @struct
 * @stability external
 */
export interface MonitorReference {
    /**
     * The Arn of the Monitor resource.
     */
    readonly monitorArn: string;
}
/**
 * Indicates that this resource can be referenced as a Scope.
 *
 * @stability experimental
 */
export interface IScopeRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Scope resource.
     */
    readonly scopeRef: ScopeReference;
}
/**
 * A reference to a Scope resource.
 *
 * @struct
 * @stability external
 */
export interface ScopeReference {
    /**
     * The ScopeArn of the Scope resource.
     */
    readonly scopeArn: string;
}
